head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.isurCnt = 0;
scwin.chgCnt = 0;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(e) {
    try {
        if (dts_List.errorMsg) {
            alert(dts_List.errorMsg);
        } else {
            txb_TotalCnt.setValue("총 " + rowcount + "건");
        }
        if (rowcount === 0) {
            btn_excelsave.setDisabled(false);
            btn_excelsave.setBackgroundImage("../img/btn_excelsave_d.gif");
        } else {
            btn_excelsave.setDisabled(true);
            btn_excelsave.setBackgroundImage("../img/btn_excelsave.gif");
        }
        scwin.isurCnt = rowcount;

        // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20210528
        btn_search.setDisabled(true);
        btn_search.setBackgroundImage("../img/btn_select.gif");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS27100.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_search_onclick
 * @description 「조회」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_search_onclick = async function(e) {
    try {
        await scwin.ins_search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS27100.btn_search_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function(e) {
    try {
        await $c.win.alert(dts_List);
        scwin.isurCnt = 0;
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS27100.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_excelsave_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_excelsave_onclick = function(e) {
    try {
        const today = $c.ut.cGetToday("yyyymmddhhmmss");
        let title = "";
        let xls_path = "";
        if (tab_IsurInfo.getSelectedTabIndex() === "1") {
            if (scwin.isurCnt === 0) {
                alert("해당 데이터가 없습니다.\n 조회를 먼저 실행하십시요");
                return;
            }
            title = "발행기관 다운로드";
            xls_path = $c.session.getExcelDownPath() + today + "_" + title + ".xls";

            grd_Grid.GridToOffice(title, xls_path, 8, 0);
            // grd_Grid.GridToExcel(title, "", "8");

        } else if (tab_IsurInfo.getSelectedTabIndex() === "2") {
            if (scwin.chgCnt === 0) {
                alert("해당 데이터가 없습니다.\n 조회를 먼저 실행하십시요");
                return;
            }
            title = "회사명 변경내역 다운로드";
            xls_path = "c:\\isinDownload\\" + today + "_" + title + ".xls";

            grd_Grid2.GridToOffice(title, xls_path, 8, 0);
            // grd_Grid2.GridToExcel(title, "", "8");

        }
        $c.stf.doLogSave("ULDINS25000.gfm", SCREN_PROCS_TP_CD_07);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS27100.btn_excelsave_onclick" });
    }
};

/**
 * @method
 * @name dts_ChgList_OnLoadCompleted
 * @description dts_ChgList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.dts_ChgList_OnLoadCompleted = function(e) {
    try {
        if (dts_ChgList.errorMsg) {
            alert(dts_ChgList.errorMsg);
        } else {
            txb_TotalCnt.setValue("총 " + rowcount + "건");
        }
        if (rowcount === 0) {
            btn_excelsave.setDisabled(false);
            btn_excelsave.setBackgroundImage("../img/btn_excelsave_d.gif");
        } else {
            btn_excelsave.setDisabled(true);
            btn_excelsave.setBackgroundImage("../img/btn_excelsave.gif");
        }
        scwin.chgCnt = rowcount;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS27100.dts_ChgList_OnLoadCompleted" });
    }
};

