/**
 * @method
 * @name dts_COM_ATTR_TP_CD_OnLoadCompleted
 * @description dts_COM_ATTR_TP_CD 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.dts_COM_ATTR_TP_CD_OnLoadCompleted = function(e) {
    try {
        for (let i = dts_COM_ATTR_TP_CD.CountRow; i > 0; i--) {
            if (dts_COM_ATTR_TP_CD.NameValue(i, "VALUE") === "1") {

                // ********************************************************************
                // [WebSquare 전환 추가] 원본 소스와 비교 필요
                //
                // ********************************************************************

                /*ORG SRC: dts_COM_ATTR_TP_CD.NameValue(i, "TEXT") = "1 주식회사";*/
                X = "1 주식회사";
            } else if (dts_COM_ATTR_TP_CD.NameValue(i, "VALUE") === "2") {

                // ********************************************************************
                // [WebSquare 전환 추가] 원본 소스와 비교 필요
                //
                // ********************************************************************

                /*ORG SRC: dts_COM_ATTR_TP_CD.NameValue(i, "TEXT") = "2 증권투자회사";*/
                X = "2 증권투자회사";
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS27100.dts_COM_ATTR_TP_CD_OnLoadCompleted" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name ins_search
 * @description 발행기관 다운로드  목록 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search = async function() {
    // 발행기관 체크
    if (txb_FROM_ISUR_CD.getValue() > txb_TO_ISUR_CD.getValue()) {
        alert("검색시작 발행기관코드가 검색종료 발행기관코드보다 큽니다.");

        txb_FROM_ISUR_CD.focus();
        return false;
    }

    // 코드부여일 체크
    if ($c.stf.compareFromToDate2(edt_FROM_STD_CD_GRNT_DD, edt_TO_STD_CD_GRNT_DD) === false) {
        return false;
    }

    // 데이터셋 초기화
    dts_List.ClearData();
    tab_IsurInfo.activeindex = "1";

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20210528
    btn_search.setDisabled(false);
    btn_search.setBackgroundImage("../img/btn_select_d.gif");
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name ins_search_chg
 * @description 회사명 변경내역  목록 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search_chg = async function() {
    // 발행기관 체크
    if (txb_FROM_ISUR_CD.getValue() > txb_TO_ISUR_CD.getValue()) {
        alert("검색시작 발행기관코드가 검색종료 발행기관코드보다 큽니다.");

        txb_FROM_ISUR_CD.focus();
        return false;
    }

    // 데이터셋 초기화
    dts_ChgList.ClearData();
    tab_IsurInfo.activeindex = "2";

    const sbmOptions = {
        id : "sbm_dts_ChgList",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_ChgList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name gridCtrl
 * @description 체크박스 체크 시 그리드 항목 show
 * @param {*} pObj pObj
 * @returns {void}
 * @hidden N
 */
scwin.gridCtrl = function(pObj) {
    let sColId = pObj.id;
    sColId = sColId.replace("ckb_", "");
    const bChecked = pObj.getValue();
    if (bChecked === "Y" && $c.cm.getColumnProp(grd_Grid, sColId, "Show") !== "TRUE") {

        $c.cm.setColumnProp(grd_Grid, sColId, "Show", true);
    } else if (bChecked === "N" && $c.cm.getColumnProp(grd_Grid, sColId, "Show") === "TRUE") {

        $c.cm.setColumnProp(grd_Grid, sColId, "Show", false);
    }
    // grd_Grid.AutoResizeAllCol(true);

};

/**
 * @method
 * @name allCheck
 * @description 전체선택 체크 시 나머지 모두 언체크.
 * @returns {void}
 * @hidden N
 */
scwin.allCheck = function() {
    if (ckb_ALL.getValue() === "Y") {
        ckb_StandardALL.setValue("Y");
        scwin.allStandardCheck();
        ckb_UniqueALL.setValue("Y");
        scwin.allUniqueCheck();
    } else {
        ckb_StandardALL.setValue("N");
        scwin.allStandardCheck();
        ckb_UniqueALL.setValue("N");
        scwin.allUniqueCheck();
    }
};

/**
 * @method
 * @name allStandardCheck
 * @description 전체선택 체크 시 체크.
 * @returns {void}
 * @hidden N
 */
scwin.allStandardCheck = function() {
    let sAllChecked = ckb_StandardALL.getValue();

    let oCheckBoxs = document.getElementsByName("std_ckb");
    for (let nRow = 0; nRow < oCheckBoxs.length; nRow++) {
        oCheckBoxs[nRow].checked = (sAllChecked === "Y") ? true : false;
        scwin.gridCtrl(oCheckBoxs[nRow]);
    }
};

/**
 * @method
 * @name allUniqueCheck
 * @description 고유정보 체크 시 체크.
 * @returns {void}
 * @hidden N
