/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.gform_onload = function() {
    panel_5.hide();
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);

    fn_CtrlBtn("no_data");

    ins_combo_set(dts_SPOT_ISU_TRD_MKT_TP_CD, "ULDINS25000.gfm", SCREN_PROCS_TP_CD_01, "01213", "ALL"); // 현물종목거래시장구분코드

    ins_combo_set(dts_LIST_STAT_CD, "ULDINS25000.gfm", SCREN_PROCS_TP_CD_01, "00714", "ALL"); // 00714 - 시장구분

    ins_combo_set(dts_COM_ATTR_TP_CD, "ULDINS25000.gfm", SCREN_PROCS_TP_CD_01, "00840", "ALL"); // 회사속성

    ckb_StandardALL.setValue("Y");
    scwin.allStandardCheck();
    label_19.hide();
    ckb_UniqueALL.hide();
    const array_grid = [grd_Grid, grd_Grid2];

    setResizeGrid(array_grid, 310);
};

